var i=`0044-zeberka`;var t=`world-0044`;var a=`PL`;var r=`eastern-europe`;var o=4;var s=87;var l={en:`Żeberka`,ua:`Запечені реберця по-польськи`};var d={en:`A classic dish from Poland, featuring pork ribs, garlic, parsley. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Польща. Основні складники: свинячі ребра, часник, петрушка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 20 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 20 хвилин.`,t:[`marinating`],m:20,i:[[`pork-ribs`,900,`g`],[`garlic`,4,`clove`],[`dried-marjoram`,3,`g`],[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`]]},{en:`Roast in a preheated 190°C oven for about 65 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 65 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:65,i:[[`sunflower-oil`,25,`ml`],[`honey`,40,`g`],[`dijon-mustard`,30,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,15,`g`]]}];var u={slug:i,id:t,country:`PL`,region:r,servings:4,minutes:87,title:l,text:d,steps:g};export{a as country,u as default,t as id,s as minutes,r as region,o as servings,i as slug,g as steps,d as text,l as title};